#![allow(unused_imports)]
use verus::prelude::*;

verus! {

    /// copy takes a reference to a Vec<i8> and returns a fresh Vec<i8>
    /// that is an exact element‐for‐element copy of the input.
    pub fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
        ensures
            // The output has the same length as the input
            result.len() == arr.len(),
            // For every valid index, the elements agree
            forall |i: usize| i < arr.len() ==> result[i] == arr[i]
    {
        let mut result: Vec<i8> = Vec::new();
        let mut i: usize = 0;

        // Loop to copy each element one by one
        while i < arr.len() {
            // Invariant: i does not exceed arr.len()
            invariant i <= arr.len();
            // Invariant: we've copied exactly i elements so far
            invariant result.len() == i;
            // Invariant: those i elements match the first i elements of arr
            invariant forall |j: usize| j < i ==> result[j] == arr[j];
            // This loop measure ensures termination
            decreases arr.len() - i;

            // Copy the next element
            result.push(arr[i]);
            i += 1;
        }

        // Return the newly built vector
        result
    }

}